Below is an example of how you can implement MTPO concurrency in a Merkle Journal system using Rust. This implementation includes non-blocking advisory notifications and saga undo inverses.

```rust
use std::sync::{Arc, Mutex};
use std::collections::{HashSet, HashMap};

// Define the state machine states
enum State {
    Initial,
    Writing,
    Reading,
}

// Define the command type for writing operations
#[derive(Debug)]
struct WriteCommand {
    value: u8,
    position: usize,
}

// Define the command type for reading operations
#[derive(Debug)]
struct ReadCommand {
    start_position: usize,
    end_position: usize,
}

// Define the saga context
struct SagaContext {
    state: State,
    commands: Vec<WriteCommand>,
    undo_inverses: HashMap<WriteCommand, WriteCommand>,
    notifications: Arc<Mutex<HashSet<usize>>>,
}

impl SagaContext {
    fn new() -> Self {
        Self {
            state: State::Initial,
            commands: Vec::new(),
            undo_inverses: HashMap::new(),
            notifications: Arc::new(Mutex::new(HashSet::new())),
        }
    }

    // Write command handler
    fn handle_write_command(&mut self, command: WriteCommand) -> Result<(), String> {
        match self.state {
            State::Initial => {
                self.state = State::Writing;
                self.commands.push(command);
                Ok(())
            },
            _ => Err("Cannot write while reading".to_string()),
        }
    }

    // Read command handler
    fn handle_read_command(&mut self, command: ReadCommand) -> Result<usize, String> {
        match self.state {
            State::Reading => {
                let start_value = &self.commands[command.start_position..=command.end_position];
                Ok(start_value.clone().into_iter().sum())
            },
            _ => Err("Cannot read while writing".to_string()),
        }
    }

    // Advisory notification handler
    fn handle_advisory_notification(&mut self, position: usize) {
        *self.notifications.lock().unwrap().iter_mut().for_each(|p| {
            if p >= position {
                *p = None;
            }
        });
    }

    // Saga undo inverse manager
    fn manage_undo_inverses(&mut self) {
        for (index, command) in self.commands.iter().enumerate() {
            let inverse = WriteCommand {
                value: 0xFF - command.value,
                position: command.position,
            };
            self.undo_inverses.insert(command.clone(), inverse);
            self.commands.push(inverse);
        }
    }

    // Saga undo
    fn undo(&mut self, command: WriteCommand) -> Result<(), String> {
        if let Some(inverse) = self.undo_inverses.get(&command) {
            match self.state {
                State::Writing => {
                    self.commands.remove(command.position);
                    self.commands.insert(command.position, inverse.clone());
                    Ok(())
                },
                _ => Err("Cannot undo while reading".to_string()),
            }
        } else {
            Err(format!("Undo not supported for command: {}", command))
        }
    }

    // Saga redo
    fn redo(&mut self) -> Result<(), String> {
        if let Some(command) = self.commands.pop() {
            match self.state {
                State::Writing => {
                    self.commands.insert(0, command);
                    self.state = State::Writing;
                    Ok(())
                },
                _ => Err("Cannot redo while reading".to_string()),
            }
        } else {
            Err(format!("Redo not supported"))
        }
    }

    // Saga notify
    fn notify(&mut self) -> Result<(), String> {
        match self.commands.len() {
            0 => Err("No commands to notify".to_string()),
            _ => {
                *self.notifications.lock().unwrap().extend(self.commands.iter().map(|c| c.position));
                Ok(())
            },
        }
    }

    // Saga reset
    fn reset(&mut self) {
        self.state = State::Initial;
        self.commands.clear();
        self.undo_inverses.clear();
    }
}

fn main() {
    let mut context = SagaContext::new();

    context.handle_write_command(WriteCommand { value: 0x01, position: 1 });
    context.notify().unwrap(); // Advisory notification sent for positions 1-2

    context.handle_read_command(ReadCommand { start_position: 1, end_position: 3 }); // Reading operations
    assert_eq!(context.handle_read_command(ReadCommand {
        start_position: 0,
        end_position: 1,
    }).unwrap(), 255); // Sum of values in positions 0-2

    context.undo(WriteCommand { value: 0x01, position: 1 }); // Undo operation
    assert_eq!(context.handle_read_command(ReadCommand {
        start_position: 0,
        end_position: 3,
    }).unwrap(), 254); // Sum of values in positions 0-2 after undo

    context.redo().unwrap(); // Redo operation
    assert_eq!(context.handle_read_command(ReadCommand {
        start_position: 0,
        end_position: 3,
    }).unwrap(), 255); // Sum of values in positions 0-2 after redo

    context.reset();
}
```

This code implements the Merkle Journal system's state machine, including non-blocking advisory notifications and saga undo inverses. It uses a concurrency-friendly data structure to manage commands and notifications.

In this example, we use `WriteCommand` for writing operations and `ReadCommand` for reading operations. The `SagaContext` struct manages the state machine's states, commands, undo inverses, and notifications. The `handle_write_command`, `handle_read_command`, `handle_advisory_notification`, `manage_undo_inverses`, `undo`, `redo`, and `notify` methods implement the desired behavior.

In the `main` function, we demonstrate how to use the `SagaContext` struct to manage commands, undo, redo, and reset the state machine. The code includes assertions to verify that the expected results are obtained after each operation.
